class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxLength : float
  + minLength : float
}

class HallOfFame {
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + initialBlockCount : int
}

class Cell {
  + gridX : int
  + gridY : int
}

class GameSession {
  + currentScore : int
  + currentLives : int
}

class ScoreEntry {
  + score : int
}

Admin "1" -- "*" Game : manages
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "*" Block
Game "1" *-- "*" GameSession
Game "1" *-- "*" ScoreEntry
Level "1" *-- "*" Cell
Cell "0..1" -- "0..1" Block : contains

Admin "0..1" -- "0..1" Game : admin_of
Player "0..*" -- "0..1" Game : plays

ScoreEntry "0..*" -- "1" Player : belongs_to
ScoreEntry "0..*" -- "1" Game : recorded_in

@enduml

